export class CompletionNotice {
 constructor({now=()=>Date.now(),schedule=(fn,ms)=>setTimeout(fn,ms),cancel=id=>clearTimeout(id),onExpire=()=>{}}={}){this.now=now;this.schedule=schedule;this.cancel=cancel;this.onExpire=onExpire;this.reset()}
 reset(){if(this.timer!=null)this.cancel(this.timer);this.key=null;this.until=0;this.timer=null}
 observe(key){if(this.key===key)return false;this.reset();this.key=key;this.until=this.now()+5000;this.timer=this.schedule(()=>{this.timer=null;this.onExpire()},5000);return true}
 get visible(){return this.key!==null&&this.now()<this.until}
}
// A compact, nonmodal panel; closing the panel never cancels live simulated orders.
export class LightningPanel {
 constructor({onOrder,onProtection,onCancel,onCancelProtection,onCancelAll,onMessage,onProtectionSide}){
  this.onProtectionSide=onProtectionSide;this.onOrder=onOrder;this.onProtection=onProtection;this.onCancel=onCancel;this.onCancelProtection=onCancelProtection;this.onMessage=onMessage;this.tab='market';
  const el=document.createElement('section');this.el=el;el.id='lightningPanel';el.hidden=true;el.className='lightningPanel';el.setAttribute('role','dialog');el.setAttribute('aria-label','閃電下單');el.setAttribute('aria-modal','false');
  const field=(id,label,value='1',min='1')=>`<label>${label}<input id="${id}" type="number" value="${value}" min="${min}" step="1" aria-label="${label}"></label>`;
  const row=(key,side,title,button)=>`<div class="fxOrderRow"><strong class="${side===1?'up':'down'}">${title}</strong>${field('fx'+key+'Price',title+'價位','')}${field('fx'+key+'Qty',title+'口數')}<button class="${side===1?'buy':'sell'}" data-action="${key}">${button}</button></div>`;
  el.innerHTML=`<div class="fxHandle" tabindex="-1"><strong>ϟ 閃電下單</strong><button id="fxCancelAll" class="fxCancelAll" title="刪除所有未成交委託（D）">刪單 <kbd>D</kbd></button><span>拖曳移動</span><button id="fxClose" aria-label="關閉閃電下單">× <kbd>A</kbd></button></div><div id="fxQuote" class="fxQuote">載入行情中</div><div class="fxTabs" role="tablist" aria-label="下單方式"><button role="tab" data-fxtab="market" aria-selected="true">現價</button><button role="tab" data-fxtab="limit" aria-selected="false">限價</button><button role="tab" data-fxtab="protection" aria-selected="false">停利停損</button><button role="tab" data-fxtab="trigger" aria-selected="false">觸價</button></div><div class="fxBody"><section data-fxpane="market"><div class="fxMarketRow">${field('fxMarketQty','現價口數')}<button class="buy" data-action="marketBuy">← 買進</button><button class="sell" data-action="marketSell">賣出 →</button></div><p>設定口數後，鍵盤 ← 買進、→ 賣出。輸入欄位內不下單。</p></section><section data-fxpane="limit" hidden>${row('limitBuy',1,'限價買進','下單')}${row('limitSell',-1,'限價賣出','下單')}<p>買進不高於設定價；賣出不低於設定價。委託後才開始判定。</p></section><section data-fxpane="protection" hidden><div class="fxProtectionRow"><strong>停利</strong><span id="fxTPState">關閉</span>${field('fxTP','停利點數','100','1')}${field('fxTPQty','停利口數')}<button class="primary" data-action="protectionTP">開啟停利</button><button data-action="stopProtectionTP">關閉停利</button></div><div class="fxProtectionRow"><strong>停損</strong><span id="fxSLState">關閉</span>${field('fxSL','停損點數','50','1')}${field('fxSLQty','停損口數')}<button class="primary" data-action="protectionSL">開啟停損</button><button data-action="stopProtectionSL">關閉停損</button></div><p>兩項預設關閉，分別開啟或關閉。單獨調整保留另一項與成本基準；空手先等待下次成交。任一側成交後本組結束，口數最多為剩餘持倉。</p></section><section data-fxpane="trigger" hidden>${row('triggerBuy',1,'觸價買進','啟動')}${row('triggerSell',-1,'觸價賣出','啟動')}<p>設定價高於現價，等待上漲觸及；低於現價，等待下跌觸及。觸發後下一筆成交，買賣兩側獨立。</p></section></div><div id="fxMessage" class="fxMessage" role="status">模擬交易 · 未送出委託</div><div id="fxPending" class="fxPending" aria-label="啟動中的委託"></div>`;
  this.completion=new CompletionNotice({onExpire:()=>{el.querySelector('[data-completion]')?.remove();if(this.messageVersion===this.completionMessageVersion)this.message('模擬交易');this.clamp()}});
  document.body.append(el);el.querySelector('#fxCancelAll').onclick=()=>onCancelAll();el.querySelector('#fxClose').onclick=()=>this.hide();
  el.querySelectorAll('[data-fxtab]').forEach(b=>b.onclick=()=>{this.tab=b.dataset.fxtab;el.querySelectorAll('[data-fxtab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));el.querySelectorAll('[data-fxpane]').forEach(x=>x.hidden=x.dataset.fxpane!==this.tab);this.clamp()});
  el.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>this.submit(b.dataset.action));
  el.querySelector('#fxPending').onclick=e=>{const b=e.target.closest('button[data-cancel]');if(b)this.onCancel(Number(b.dataset.cancel));if(e.target.closest('[data-cancel-plan]'))this.onCancelProtection()};

  const handle=el.querySelector('.fxHandle');let drag=null;handle.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button'))return;const box=el.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:box.left,top:box.top};handle.setPointerCapture(e.pointerId);e.preventDefault()});handle.addEventListener('pointermove',e=>{if(!drag)return;el.style.left=drag.left+e.clientX-drag.x+'px';el.style.top=drag.top+e.clientY-drag.y+'px';el.style.right='auto';el.style.bottom='auto';this.clamp()});for(const type of ['pointerup','pointercancel'])handle.addEventListener(type,()=>drag=null);window.addEventListener('resize',()=>this.clamp());
 }
 get visible(){return !this.el.hidden}
 toggle(price){if(this.visible)this.hide();else this.show(price)}
 show(price){for(const id of ['limitBuy','limitSell']){const f=this.el.querySelector('#fx'+id+'Price');if(!f.value&&price)f.value=price}this.el.hidden=false;this.el.querySelector('.fxHandle').focus();this.clamp()}
 hide(){this.el.hidden=true;document.getElementById('chart')?.focus()}
 clamp(){if(!this.visible)return;const b=this.el.getBoundingClientRect(),x=Math.max(4,Math.min(innerWidth-b.width-4,b.left)),y=Math.max(4,Math.min(innerHeight-b.height-4,b.top));this.el.style.left=x+'px';this.el.style.top=y+'px';this.el.style.right='auto';this.el.style.bottom='auto'}
 value(id){return Number(this.el.querySelector('#'+id).value)}
 submit(action){try{if(/^(?:stopProtection|protection)(TP|SL)$/.test(action)){const key=action.endsWith('TP')?'TP':'SL';this.onProtectionSide(key.toLowerCase(),{enabled:!action.startsWith('stop'),points:this.value('fx'+key),qty:this.value('fx'+key+'Qty')})}else if(action.startsWith('market'))this.onOrder({side:action==='marketBuy'?1:-1,qty:this.value('fxMarketQty'),reason:'閃電現價'});else{const side=action.endsWith('Buy')?1:-1;this.onOrder({side,qty:this.value('fx'+action+'Qty'),level:this.value('fx'+action+'Price'),...(action.startsWith('limit')?{kind:'limit',reason:'閃電限價'}:{touch:true,reason:'閃電觸價'})})}}catch(e){this.onMessage(e.message)}}
 message(text){this.messageVersion=(this.messageVersion??0)+1;this.el.querySelector('#fxMessage').textContent=text}
 update({session,quote,orders=[],plan,disabled=false,auto=false}){
  if(session!==this.session){this.session=session;this.lastFill=null;this.completion.reset();}
  const filled=orders.filter(o=>o.status==='filled').at(-1);if(filled&&filled!==this.lastFill){this.lastFill=filled;this.message(`● #${filled.id} ${filled.side===1?'買進':'賣出'} ${filled.filledQty??filled.qty}口，成交 ${filled.fillPrice}`)}
  this.el.querySelector('#fxQuote').textContent=quote;this.el.querySelectorAll('[data-action]').forEach(b=>b.disabled=disabled||(auto&&!/Protection|protection/.test(b.dataset.action)));this.canProtect=!disabled;for(const key of ['TP','SL']){const active=plan&&['waiting-position','active','triggered'].includes(plan.status)&&plan[key.toLowerCase()]>0;const state=this.el.querySelector('#fx'+key+'State');state.textContent=active?(plan.status==='waiting-position'?'已開啟・等待持倉':plan.status==='triggered'?'已觸發待成交':'已開啟・'+plan[key.toLowerCase()]+'點 / '+plan[key.toLowerCase()+'Qty']+'口'):'關閉';this.el.querySelector('[data-action="stopProtection'+key+'"]').disabled=disabled||!active;this.el.querySelector('[data-action="protection'+key+'"]').disabled=disabled||plan?.status==='triggered';for(const suffix of ['', 'Qty'])this.el.querySelector('#fx'+key+suffix).disabled=disabled}
  const pending=orders.filter(o=>['waiting','ready'].includes(o.status));this.el.querySelector('#fxCancelAll').disabled=disabled||(!pending.length&&!['waiting-position','active','triggered'].includes(plan?.status));const labels={waiting:'等待到價',ready:'等待下一筆成交'};const rows=pending.map(o=>`<div><span>#${o.id} ${o.close?'平倉':o.side===1?'買':'賣'} ${o.qty}口 ${o.condition?(o.condition==='gte'?'≥ ':'≤ '):''}${o.level??'現價'} · ${labels[o.status]}</span><button data-cancel="${o.id}" aria-label="取消委託${o.id}">取消</button></div>`);
  if(plan&&['waiting-position','active','triggered'].includes(plan.status)){const text=plan.status==='waiting-position'?'停利停損：等待持倉成交':plan.status==='triggered'?'● '+plan.triggerReason+'已觸發':`停利停損已啟動 · 基準 ${Number(plan.anchor.toFixed(2))}`;rows.unshift(`<div><span class="${plan.status==='triggered'?'blink':''}">${text}</span><button data-cancel-plan>取消</button></div>`)}
  if(plan?.status==='completed'){if(this.completion.observe(plan))this.completionMessageVersion=this.messageVersion;if(this.completion.visible)rows.unshift(`<div data-completion><span class="blink">● ${plan.triggerReason}已成交，本組已結束</span></div>`)}
  const target=this.el.querySelector('#fxPending'),html=rows.join('');if(target.innerHTML!==html){target.innerHTML=html;this.clamp()}
 }
}
